async function dispatch(args) {
  if (args.includes('--version')) return 'version'
  if (args.includes('--remote')) return await import('./remote.js')
  return await import('./interactive.js')
}

dispatch(['--version', '--remote']) // 'version'

let s = { phase: 'model', pendingTool: null, reason: null }
// model이 tool call을 냄
